import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"设计取舍","description":"","frontmatter":{},"headers":[],"relativePath":"why.md","filePath":"why.md","lastUpdated":1794049926000}`),a={name:`why.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="设计取舍" tabindex="-1">设计取舍 <a class="header-anchor" href="#设计取舍" aria-label="Permalink to “设计取舍”">​</a></h1><p>本页说明本项目的架构选择、设计原则与已知限制，适用于评估是否采用本项目的技术负责人与开发者。完整的决策记录在仓库 <code>plans/</code> 目录的总体方案里（全局决定 D1–D12）。</p><h2 id="为什么是能力包-操作契约" tabindex="-1">为什么是能力包 + 操作契约 <a class="header-anchor" href="#为什么是能力包-操作契约" aria-label="Permalink to “为什么是能力包 + 操作契约”">​</a></h2><p>XiHan.Framework 的应用写法是能力包（<code>IFeature</code> + 清单）、操作契约（一个方法一个操作）、管道阶段中间件、RFC 9457 错误与按操作 ID 推导的路由。BasicApp 完全照这套写法组织，不保留 Controller、约定扫描或拦截器一类平行机制，换来的是：</p><ul><li>一份契约同时得到 HTTP 路由、OpenAPI、gRPC 方法、MCP 工具与 AI 工具，认证、租户、权限、校验与审计在各协议上一致。</li><li>权限目录、菜单、前端类型都从代码登记派生，不用两处维护。</li><li>每个包自带实体、操作、权限、页面、种子、文案与测试，可以按 Tier 单独理解和裁剪。</li></ul><h2 id="全局决定" tabindex="-1">全局决定 <a class="header-anchor" href="#全局决定" aria-label="Permalink to “全局决定”">​</a></h2><table tabindex="0"><thead><tr><th>决定</th><th>理由</th></tr></thead><tbody><tr><td>能力包 + 操作契约；HTTP 路由由操作 ID 推导，错误用 RFC 9457，成功响应不加信封</td><td>框架的标准写法，一份契约服务 HTTP、gRPC、OpenAPI、MCP 与 AI 工具</td></tr><tr><td>按 Tier 0–3 分包，只能向下依赖，同层经 <code>Contracts</code> 协作</td><td>包的边界清楚，可选模块能整体关掉；层级由架构测试检查</td></tr><tr><td>主键 UUID v7；租户 ID 是字符串；平台数据不实现 <code>IMultiTenant</code>；时间统一为 UTC <code>DateTimeOffset</code></td><td>框架仓储对 <code>IMultiTenant</code> 严格相等过滤，平台数据放在过滤之外最直接；UUID 时间有序、JSON 即字符串，前端没有精度问题</td></tr><tr><td>权限码 <code>&lt;包&gt;.&lt;资源&gt;.&lt;动作&gt;</code>，操作 ID <code>&lt;资源&gt;.&lt;动词&gt;</code>，按钮直接用操作的权限码</td><td>权限目录从操作登记派生，不另维护一套按钮码</td></tr><tr><td>前端接口层由 <code>openapi.json</code> 生成，错误按 <code>code</code> 分支</td><td>前后端契约不一致由生成器与 CI 检出</td></tr><tr><td>框架只校验令牌与判定策略；签发、刷新、会话、双因素、第三方登录、模仿都是 Identity 的操作</td><td>认证流程属于应用，框架保持通用</td></tr><tr><td>表结构由应用管理：<code>Schema/&lt;版本&gt;/*.sql</code> + 版本台账，<code>InitTables</code> 只开在开发环境</td><td>正式库的每一步变更可审阅、可重复执行</td></tr></tbody></table><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to “设计原则”">​</a></h2><p><strong>装配显式。</strong> 不用约定扫描、<code>IScopedDependency</code> 或拦截器。服务在 <code>IFeature.Configure</code> 中登记，横切逻辑是管道阶段中间件。一个包提供了什么，以它的 Feature 类为准。</p><p><strong>单一事实源。</strong> 权限目录来自操作登记，菜单来自页面登记，前端类型来自 OpenAPI，枚举文案来自后端消息目录。</p><p><strong>边界刚、内部柔。</strong> 包之间只经 <code>Contracts</code> 的接口与消息主题往来；包内部的目录名全仓统一（<code>PackageStructureTests</code> 守护）。</p><p><strong>批量优先。</strong> 对已有对象按标识的写操作（删除、启停、授权、撤销）只提供集合入参，单条是一元集合，响应逐项给结果。</p><p><strong>失败以值表示。</strong> 可恢复的失败返回 <code>Result</code> / <code>Error</code>，错误码 <code>&lt;包&gt;_&lt;KIND&gt;_&lt;NNN&gt;</code> 决定 HTTP 状态与 gRPC 状态；异常只用于编程错误与基础设施故障。</p><p><strong>缺省收紧。</strong> 每个操作必须显式声明 <code>Expose</code>（编译期诊断 <code>XHG004</code>）：管理操作只发布到 HTTP，选定的只读操作才发布到 MCP 与 AI 工具，供内部服务调用的才发布到 gRPC；权限码缺省要求认证。</p><p><strong>文案与代码分离。</strong> 每个包一个消息常量类和 10 种区域的 JSON 文案，错误只携带键与参数，由宿主按 <code>Accept-Language</code> 翻译。</p><h2 id="代价与限制" tabindex="-1">代价与限制 <a class="header-anchor" href="#代价与限制" aria-label="Permalink to “代价与限制”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>登记代码多</td><td>没有约定扫描，仓储、服务、权限、页面、中间件与作业都要在 Feature 里写明；换来的是装配可读、可测</td></tr><tr><td>跨库事务</td><td>平台库与独立库租户的写入是顺序提交，不是两阶段提交；租户开通这类跨库写路径由操作做补偿</td></tr><tr><td>数据库</td><td>PostgreSQL 是缺省与 CI 口径；读写分离只在 PostgreSQL 上实测过</td></tr><tr><td>单体部署</td><td>一个宿主装全部能力包；多实例靠 Redis 与 RabbitMQ 共享缓存、消息与实时推送，见<a href="./deployment#多实例部署">部署</a></td></tr><tr><td>Native AOT</td><td>不是目标。SqlSugar、MailKit、Scriban 等依赖不支持 AOT；操作登记仍按框架要求使用源生成的 <code>JsonSerializerContext</code></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="./overview">系统概述</a> · <a href="./backend/introduction">后端架构总览</a> · <a href="./getting-started">快速开始</a></li></ul>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};